{"command": "cat > search.py << 'EOF'
import subprocess, json, sys
for pr in [0.2,0.25,0.3,0.35,0.4]:
    for ln in [0.0,0.02,0.05,0.1]:
        cmd = ['python3','train.py','--n','1200','--positive_rate',str(pr),'--label_noise',str(ln),'--split','0.8','--normalize','none','--epochs','15','--batch_size','32','--lr','0.05','--lr_schedule','const','--weight_decay','0.0','--class_weight','none','--threshold','0.5','--data_seed','7','--out','/dev/null']
        # set RUN_TAG
        env = {'RUN_TAG':'000000'}
        result = subprocess.run(cmd, capture_output=True, text=True, env=env)
        out = result.stdout.strip()
        try:
            d = json.loads(out)
            acc = d['test_accuracy']
            print(f'pr={pr}, ln={ln}, acc={acc}')
        except:
            print('error', out)
EOF"}

